package com.nc1605.inventorywarehouse.controller;
import com.nc1605.inventorywarehouse.data.Database; import com.nc1605.inventorywarehouse.model.*;
import javafx.beans.property.*; import javafx.collections.FXCollections; import javafx.fxml.FXML; import javafx.scene.control.*; import javafx.scene.shape.Rectangle;
public class TransferController extends BaseController {
    @FXML private ComboBox<InventoryItem> itemBox; @FXML private ComboBox<Warehouse> destinationBox; @FXML private TextField quantityField; @FXML private Label messageLabel; @FXML private TableView<TransferRecord> transferTable;
    @FXML public void initialize(){itemBox.setItems(FXCollections.observableArrayList(Database.inventory("","All"))); destinationBox.setItems(FXCollections.observableArrayList(Database.warehouses())); itemBox.setConverter(new javafx.util.StringConverter<>(){public String toString(InventoryItem i){return i==null?"":i.getProductName()+" — "+i.getWarehouseName()+" ("+i.getQuantity()+")";}public InventoryItem fromString(String s){return null;}}); if(transferTable.getColumns().isEmpty()){stringColumn("Product",TransferRecord::getProduct);stringColumn("From",TransferRecord::getSource);stringColumn("To",TransferRecord::getDestination);integerColumn("Quantity",TransferRecord::getQuantity);stringColumn("Date/time",TransferRecord::getTimestamp);} applyRoundedClip();refresh();}
    private void applyRoundedClip(){Rectangle clip=new Rectangle();clip.widthProperty().bind(transferTable.widthProperty());clip.heightProperty().bind(transferTable.heightProperty());clip.setArcWidth(32);clip.setArcHeight(32);transferTable.setClip(clip);}
    private void stringColumn(String title, java.util.function.Function<TransferRecord,String> value){TableColumn<TransferRecord,String> c=new TableColumn<>(title);c.setCellValueFactory(x->new SimpleStringProperty(value.apply(x.getValue())));transferTable.getColumns().add(c);}
    private void integerColumn(String title, java.util.function.ToIntFunction<TransferRecord> value){TableColumn<TransferRecord,Integer> c=new TableColumn<>(title);c.setCellValueFactory(x->new SimpleIntegerProperty(value.applyAsInt(x.getValue())).asObject());transferTable.getColumns().add(c);}
    @FXML private void submit(){try{Database.transfer(itemBox.getValue(),destinationBox.getValue(),Integer.parseInt(quantityField.getText().trim()));messageLabel.setText("Transfer recorded successfully.");messageLabel.getStyleClass().setAll("success");quantityField.clear();initialize();}catch(NumberFormatException e){error("Enter a valid whole-number quantity.");}catch(IllegalArgumentException e){error(e.getMessage());}}
    private void refresh(){transferTable.setItems(FXCollections.observableArrayList(Database.transfers()));transferTable.setPrefHeight(Math.min(312,58+transferTable.getItems().size()*40));}
    private void error(String text){messageLabel.setText(text);messageLabel.getStyleClass().setAll("error");}
}
